/* ─── bảng màu: đúng token của tap03-full.html ─── */
const TRANG="#E8E6DF", DAT="#C98A4B", BIEN="#2E6F8E", DEM="#070B16",
      SANHO="#E0705A", NHAT="#F2C14E",
      GIAY="#F6F8F5", GIAY2="#ECEFEA", BIENN="#D8ECF7", DATN="#E6E6E6",
      CHUTOI="#1C2A22", CHU="#EAF2F7", CHU2="#8FA8BA", DO="#D4523C", DEN="#0B0B0B";

/* ─── tiện ích riêng của khối 3 ─── */
function bd(root){ const V = root.querySelector("svg.bd"); V.innerHTML = ""; return V; }
function phang(root, ten){ const V = root.querySelector("svg." + ten); V.innerHTML = ""; return V; }
/* máy quay bản đồ: lia + đẩy, LUÔN còn nhịp thở nên không khung nào đứng yên */
function mcam(V, a, b, u, t){
  const e = ezo(cl(u, 0, 1));
  const w = Math.exp(lerp(Math.log(a[2]), Math.log(b[2]), e));
  ngam(V, lerp(a[0], b[0], e) + w * .0045 * Math.sin(t * .23),
          lerp(a[1], b[1], e) + w * .0035 * Math.cos(t * .19), w);
}
const mgiu = (V, a, u, t, day) => mcam(V, a, [a[0], a[1], a[2] * (day === undefined ? .93 : day)], u, t);
/* nền bản đồ Úc: biển + đất trung tính */
function nenUC(V, toi){
  el("rect", { x:-9e4, y:-9e4, width:18e4, height:18e4, fill: toi ? "#061520" : BIENN }, V);
  const g = el("g", {}, V);
  UCM.land.forEach(d => el("path", { d:d, fill: toi ? "#15293A" : DATN,
    stroke: toi ? "#24455C" : "#A9BBC7", "stroke-width":.7, "stroke-linejoin":"round",
    "vector-effect":"non-scaling-stroke" }, g));
  return g;
}
function vungUC(V, mau, mo){
  const g = el("g", { opacity: mo === undefined ? 1 : mo }, V);
  UCM.uc.forEach(d => el("path", { d:d, fill:mau, stroke:mau, "stroke-width":1.2,
    "stroke-linejoin":"round", "vector-effect":"non-scaling-stroke" }, g));
  return g;
}
/* nhãn địa danh: hộp trắng chữ đen, tam giác nhọn chỉ xuống (luật F.4) */
function nhanHop(id, ten, l, t){
  return '<div class="tx" id="' + id + '" style="left:' + l + 'px;top:' + t + 'px">' +
    '<div style="background:#FFF;color:#1C2A22;font:700 16px/1 system-ui;letter-spacing:.04em;' +
    'padding:7px 11px;border-radius:3px;white-space:nowrap;box-shadow:0 2px 10px rgba(0,0,0,.45)">' +
    ten + '</div><div style="width:0;height:0;margin:0 auto;border-left:7px solid transparent;' +
    'border-right:7px solid transparent;border-top:9px solid #FFF"></div></div>';
}
function nhanVung(id, ten, l, t, mau){
  return '<div class="tx" id="' + id + '" style="left:' + l + 'px;top:' + t + 'px;' +
    'font:700 19px/1 system-ui;letter-spacing:.16em;color:' + (mau || "#FFF") +
    ';text-shadow:0 2px 10px rgba(0,0,0,.85)">' + ten + '</div>';
}
const nguon = (id, s, l) => '<div class="tx nho" id="' + id + '" style="left:' +
  (l === undefined ? 92 : l) + 'px;top:656px">' + s + '</div>';
/* thẻ chữ biên tập giữa khung — dùng ĐÚNG 4 lần trong cả khối */
function the(id, s, mau, co){
  return '<div class="tx" id="' + id + '" style="left:0;top:' + (co === undefined ? 300 : co) +
    'px;width:1280px;text-align:center;font:300 ' + 54 + 'px/1.15 system-ui;letter-spacing:.26em;' +
    'color:' + (mau || TRANG) + ';text-shadow:0 2px 22px rgba(3,8,13,.75)">' + s + '</div>';
}
/* ĐĨA MẶT TRĂNG vẽ tay: tất định, có biển tối và vài hố — dùng lại nhiều cảnh */
function dia(p, cx, cy, r, mau, pre, sv){
  const g = el("g", {}, p);
  gradB(sv, pre, [[0,"#FFFFFF",.22],[.55,"#FFFFFF",.05],[1,"#000000",.30]]);
  el("circle", { cx:cx, cy:cy, r:r, fill: mau || TRANG }, g);
  for (let i=0;i<9;i++){
    const a = rn(i,501)*Math.PI*2, q = r*(.15+rn(i,502)*.62);
    el("circle", { cx:(cx+q*Math.cos(a)).toFixed(1), cy:(cy+q*Math.sin(a)).toFixed(1),
      r:(r*(.05+rn(i,503)*.16)).toFixed(1), fill:"#9C9A93",
      opacity:(.18+rn(i,504)*.26).toFixed(2) }, g);
  }
  el("circle", { cx:cx, cy:cy, r:r, fill:"url(#"+pre+")" }, g);
  return g;
}
/* một pha trăng: đĩa sáng bị một đĩa nền cắt đi, ph = 0 (sóc) → .5 (rằm) → 1 */
function pha(p, cx, cy, r, ph, mau, nen){
  const g = el("g", {}, p);
  el("circle", { cx:cx, cy:cy, r:r, fill: nen || "#1B2233" }, g);
  const k = Math.cos(ph*Math.PI*2);          /* 1 → -1 → 1 */
  const sang = ph<.5 ? 1 : 0;                /* nửa nào sáng */
  const d = "M"+cx+","+(cy-r)+" A"+r+","+r+" 0 0 "+(sang?1:0)+" "+cx+","+(cy+r)+
            " A"+(r*Math.abs(k)).toFixed(2)+","+r+" 0 0 "+((k<0)===(sang===1)?1:0)+" "+cx+","+(cy-r)+" Z";
  el("path", { d:d, fill: mau || TRANG }, g);
  return g;
}
/* một ụ san hô nhìn ngang: vòm đặc + bóng chân + mấy nhánh — dùng lại ở cảnh 08, 09, 10 */
function uSanHo(p, x, y, k, mo, seed){
  k = k === undefined ? 1 : k;
  seed = seed === undefined ? 0 : seed;
  const w = 88 * (.78 + rn(seed, 601) * .5);
  const h = 104 * (.62 + rn(seed, 602) * .62);
  const g = el("g", { opacity: mo === undefined ? 1 : mo,
    transform:"translate("+x+" "+y+") scale("+k.toFixed(3)+")" }, p);
  el("ellipse", { cx:0, cy:4, rx:(w*1.04).toFixed(1), ry:16, fill:"#20100C", opacity:.5 }, g);
  el("path", { d:"M"+(-w).toFixed(1)+",2 q4,"+(-h*.72).toFixed(1)+" "+(w*.44).toFixed(1)+","+
    (-h).toFixed(1)+" q"+(w*.28).toFixed(1)+",-18 "+(w*.52).toFixed(1)+",-2 q"+
    (w*.46).toFixed(1)+","+(h*.28).toFixed(1)+" "+(w*.5).toFixed(1)+","+(h+2).toFixed(1)+" Z",
    fill:"#8E4536" }, g);
  el("path", { d:"M"+(-w).toFixed(1)+",2 q4,"+(-h*.72).toFixed(1)+" "+(w*.44).toFixed(1)+","+
    (-h).toFixed(1)+" q10,-8 20,-6 q"+(-w*.3).toFixed(1)+","+(h*.44).toFixed(1)+" "+
    (-w*.27).toFixed(1)+","+(h+8).toFixed(1)+" Z", fill:"#AA5B45", opacity:.55 }, g);
  for (let q=0;q<5;q++)
    el("path", { d:"M"+(-w*.6+q*w*.3).toFixed(1)+",-2 q"+(5-q*2.4)+","+(-h*.42).toFixed(1)+
      " "+(2-q*3)+","+(-h*.7).toFixed(1), fill:"none", stroke:"#B86750",
      "stroke-width":6.5, "stroke-linecap":"round", opacity:(.64-q*.06).toFixed(2) }, g);
  return g;
}
